function gh926ResumeCliMock(opts, calls) {
    return function(args) {
        calls.cli.push(args && args.command);
        if (opts.cliError) throw new Error(opts.cliError);
        return opts.remoteUrl !== undefined ? opts.remoteUrl : 'resume output';
    };
