            console.warn('⚠️ gh-1053 spec-claim guard:', note);
        });
        return result;
    } catch (e) {
        console.warn('⚠️ gh-1053 spec-claim guard failed (continuing un-sanitized):', e.message || e);
        return { downgrades: 0, notes: [], rewrites: [] };
    }
}

