 * incidental spec mention must not demote a code-level defect blocker).
 */
function coreClaimText(body) {
    var text = String(body || '');
    for (var i = 0; i < LEADING_MARKER_RES.length; i++) {
        text = text.replace(LEADING_MARKER_RES[i], '');
