function stripBlockingMarker(text) {
   var t = text.replace(/^\s*\uD83D\uDEA8\s*/, '');
   t = t.replace(/^\s*\**\s*BLOCKING\b\**\s*[:\-–—.)]?\s*/i, '');
   return t;
}
function firstSentence(text) {
   var m = /[^.!?\n]+/.exec(text);
   return m ? m[0] : '';
}
function coreClaimText(body) {
   return firstSentence(stripBlockingMarker(String(body || '')));
}
