/** The spec-claim phrase that matched (trimmed) — '' when none. */
function findSpecClaimPhrase(text) {
    for (var i = 0; i < SPEC_CLAIM_RES.length; i++) {
        var m = SPEC_CLAIM_RES[i].exec(text);
        if (m) return m[0].trim();
